  }

  .resend-section a {
    color: var(--primary);
    text-decoration: none;
    font-weight: 600;
    cursor: pointer;
  }

  .resend-section a.disabled {
    pointer-events: none;
    color: var(--text-secondary);
  }
</style>
</head>
<body>
  <div class="container">
    <h1 class="title">أدخل الرمز</h1>
    <p class="subtitle">
      أرسلنا رمزًا مكونًا من 6 أرقام إلى <bdi dir="ltr">+966 55 123 4567</bdi>
    </p>

    <form class="code-inputs" id="codeForm">
      <input type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" data-index="0" dir="ltr">
      <input type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" data-index="1" dir="ltr">
      <input type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" data-index="2" dir="ltr">
      <input type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" data-index="3" dir="ltr">
      <input type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" data-index="4" dir="ltr">
      <input type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" data-index="5" dir="ltr">
    </form>

    <div class="countdown">إعادة الإرسال خلال <span id="timer">0:45</span></div>

    <button class="btn" id="verifyBtn" disabled>/check</button>

    <div class="resend-section">
      <a id="resendLink" class="disabled">لم llegar الرمز؟</a>
    </div>
  </div>

<script>
  const inputs = document.querySelectorAll('.code-inputs input');
  const verifyBtn = document.getElementById('verifyBtn');
  const timerEl = document.getElementById('timer');
  const resendLink = document.getElementById('resendLink');

  let countdown = 45;
  let timerInterval;

  // Convert Arabic-Indic digits to Western digits
  function toWesternDigits(str) {
    return str
      .replace(/[٠١٢٣٤٥٦٧٨٩]/g, d => d.charCodeAt(0) - 1632)
      .replace(/[۰۱۲۳۴۵۶۷۸۹]/g, d => d.charCodeAt(0) - 1728);
  }

  inputs[0].focus();

  inputs.forEach((input, index) => {
    input.addEventListener('input', () => {
      // Convert any Arabic-Indic digits to Western digits
      input.value = toWesternDigits(input.value).replace(/[^0-9]/g, '');

      if (input.value.length === 1) {
        if (index < inputs.length - 1) {
          inputs[index + 1].focus();
        } else {
          verifyBtn.disabled = false;
        }
      }
    });

    input.addEventListener('keydown', (e) => {
      if (e.key === 'Backspace' && input.value === '') {
        if (index > 0) {
          inputs[index - 1].focus();
        }
      }
    });

    input.addEventListener('paste', (e) => {
      e.preventDefault();
      const pasted = e.clipboardData.getData('text');
      const converted = toWesternDigits(pasted).replace(/[^0-9]/g, '');
      if (converted.length === 6) {
        inputs.forEach((inp, i) => {
          inp.value = converted[i] || '';
        });
        verifyBtn.disabled = false;
        inputs[5].focus();
      }
    });
  });

  startCountdown();

  function startCountdown() {
    timerInterval = setInterval(() => {
      countdown--;
      const mins = Math.floor(countdown / 60);
      const secs = countdown % 60;
      timerEl.textContent = `${mins}:${secs.toString().padStart(2, '0')}`;

      if (countdown <= 0) {
        clearInterval(timerInterval);
        resendLink.classList.remove('disabled');
        resendLink.textContent = 'إعادة الإرسال';
      }
    }, 1000);
  }

  verifyBtn.addEventListener('click', () => {
    const code = Array.from(inputs).map(i => i.value).join('');
    if (code.length === 6) {
      // In a real app this would call a verification API
      alert('الرمز المُدخل: ' + code);
    }
  });

  resendLink.addEventListener('click', (e) => {
    e.preventDefault();
    if (countdown <= 0) {
      inputs.forEach(i => i.value = '');
      inputs[0].focus();
      verifyBtn.disabled = true;

      countdown = 45;
      resendLink.classList.add('disabled');
      resendLink.textContent = 'لم يصل الرمز؟';
      startCountdown();
    }
  });
</script>
</body>
</html>
